quests[76067] = { id = 76067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signed, Sealed, Self-Delivered", objectives = "<Newsy seems to want you to pick her up.>", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76072] = { id = 76072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shades of Scarlet", description = "I need your help, {name}. I thought I had achieved some semblance of peace--although my sins might not be forgiven, I could at least reunite with the spirits of my beloved family. Yet...  my wife's spirit is missing. It is as though she never existed.\n\nHallow's End draws the shades that haunt the Monastery out from the shadows. Trapped in the past, they walk the grounds repeating their nightmares.\n\nWith any luck, one of them might give us answers as to what happened to her.", completion = "<Sir Thomas is lost in thought, and jumps at your approach.>\n\n{name}! My apologies for running off back there. There are... some memories I wish never to revisit. \n\nIt would seem these cruel shades know just how to salt our wounds.\n\nCome, I think I know where to look next.", objectives = "Search for leads amongst the shades at the Scarlet Monastery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76073] = { id = 76073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Laughing Matter", description = "There is a fountain terrace at the end of this path. Before the Scourge wrought havoc across Lordaeron, I used to bring Suzannah there. I remember how certain I felt then--in myself, in the Light... in her, and my children. \n\nI wonder when it was that my path started to dim.\n\nIf there is a shade that can enlighten us, they would be at the fountain.", completion = "<Suzannah remains silent for a time.>\n\nNot so very long ago, my husband Thomas begged me to leave for Kalimdor to flee the Scourge. He hadn't come to bed that night, instead keeping vigil to protect us. The fear in his voice scared me, and the desperation in his eyes...\n\n<Suzannah gently traces a line across her palm, then clutches it tightly.>\n\nI won't abandon him. Not this time, not ever.", objectives = "Investigate the Monastery's Fountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76074] = { id = 76074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Headless Horseman, Returned", description = "Thomas retreated into the Scarlet Monastery. His ties to this place are strong, even when he is in his corrupted form.\n\nYour name is {name}, yes? My husband trusted you to help him, and so I must ask the same. I intend to give chase, but I cannot save him alone.\n\nWill you join me?", completion = "Once more I have been saved from madness. How could I ever thank you enough?", objectives = "Use the Group Finder to enter the dungeon, \"The Headless Horseman,\" and defeat the Headless Horseman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76075] = { id = 76075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Ghostly Message", description = "Excuse me, {name} is it? You've made quite a name for yourself lately, for both the living and the dead. \n\nI have in my possession the Tome of Thomas Thomson. For years it has been in my library, a reminder of times we must not forget. Imagine my surprise when the tome flings itself to the floor, falling open to a page with a single name on it.\n\nYours, {name}.\n\nIf Thomas' spirit is trying to reach you, then I think you should take this tome. Perhaps he awaits at the Scarlet Monastery?", completion = "At last, {name}. I knew you would come.\n\nI am once again in need of aid, and an adventurer of your caliber would be most welcome.", objectives = "Look for Thomas Thomson near the Scarlet Monastery in Tirisfal Glades.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76076] = { id = 76076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Small Things", description = "We had some well-meaning whelps take a few teeny objects from history. Small things can sometimes have a big impact. While the whelps are doing double chores, I need someone to return these rocks to their proper place.\n\nI know, right? Rocks? But they have to go back.", completion = "Thank you for doing that, {name}. Keeping the Timeways on track isn't always the most fun or glamorous job, and sometimes you have to do things you'd rather not. But the true timeline must go on!", objectives = "Return the Icy Rocks to Lordaeron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76081] = { id = 76081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liars of Spirit" }
quests[76083] = { id = 76083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aberrus, the Shadowed Crucible: Echoes of the Earth-Warder", description = "I sense a dark presence somewhere within these halls... something strangely familiar. Perhaps it will reveal itself as we explore the many chambers of Aberrus. If you can find evidence of this looming evil, we may be able to gain easier access to the depths below.", progress = "The knowledge gained from these may allow us to access the lower depths of Aberrus more directly.", completion = "These should allow us to descend into the depths of Aberrus more easily.", objectives = "Collect 3 Tomes of the Earth-Warder from the Echo of Neltharion within Aberrus, the Shadowed Crucible on Normal Difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76084] = { id = 76084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostfire Finesse" }
