quests[76101] = { id = 76101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tougher Down Under", description = "Quite a few uplanders have arrived since the cavern was split clean open! \n\nA friendly winged-one by the name of Vaskarn has been particularly helpful to us. She's made the guard's armor tougher and the monster hunter's weapons stronger.\n\nShe's going to be plenty valuable if you plan on taking down more giant beasties here in Zaralek!", completion = "Got quite the gear on you! Shall we see what we can make of it?", objectives = "Speak with Vaskarn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76103] = { id = 76103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to the Trading Post", description = "<The glint of a distant object catches your eye. You suddenly remember that you have tender to collect for use at T&W Trading Post.>", progress = "Did you collect this month's tender?", completion = "Hope ye like this month's collection of new and exotic wares, {name}.", objectives = "Return to the Trading Post to collect your Trader's Tender from the Collector's Cache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
