quests[76274] = { id = 76274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work It", description = "The Trial of Style gives us the opportunity to look good, {class}.\n\nThe camera makes sure we keep looking good. \n\nSo focus on me and my camera, follow my directions and I'll make sure you look fantastic!", progress = "Focus on me and follow my directions. \n\nI'll make sure you look great.", completion = "The camera doesn't lie, {name}. \n\nYou are one stylish {class}.", objectives = "Focus on the photographer and follow their directions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76275] = { id = 76275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work It", description = "The Trial of Style gives us the opportunity to look good, {class}.\n\nThe camera makes sure we keep looking good. \n\nSo focus on me and my camera, follow my directions and I'll make sure you look fantastic!", progress = "Focus on me and follow my directions. \n\nI'll make sure you look great.", completion = "The camera doesn't lie, {name}. \n\nYou are one stylish {class}.", objectives = "Focus on the photographer and follow their directions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76276] = { id = 76276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Changed Land", description = "The arrival of Amirdrassil brings great change to Azeroth. Its roots are finding a home in the soil beneath even as its branches stretch skyward to taste the air.\n\nThis is an auspicious moment, but we must not forget our allies from the Isles. Visit with those nearby to ensure they are safe and sound.", progress = "Amirdrassil has safely arrived, but we must make sure our allies are also safe and sound.", completion = "I am heartened to hear that our friends are well. Thank you for visiting them, Champion.", objectives = "Check on nearby Dragon Isles residents.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76278] = { id = 76278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work It", description = "The Trial of Style gives us the opportunity to look good, {class}.\n\nThe camera makes sure we keep looking good. \n\nSo focus on me and my camera, follow my directions and I'll make sure you look fantastic!", progress = "Focus on me and follow my directions. \n\nI'll make sure you look great.", completion = "The camera doesn't lie, {name}. \n\nYou are one stylish {class}.", objectives = "Focus on the photographer and follow their directions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76280] = { id = 76280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Moon", description = "With these offerings and water from the Well of Eternity, we have all that we need.\n\nSpeak with me when you are ready to begin the ritual.", progress = "Amirdrassil...", completion = "Amirdrassil... at last. It feels as if I have let go of a breath I did not realize I was holding. {name}, I cannot thank you enough for your aid.", objectives = "Speak with Tyrande Whisperwind in the Central Encampment to begin the ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76281] = { id = 76281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something Worth Celebrating", description = "At long last... let us celebrate all that we have overcome, and the hope that burns brightly amongst these gathered kaldorei.\n\nCome, join the festivities.", progress = "Have you thoroughly enjoyed yourself, Champion?", completion = "So much life and joy resides here beneath these branches. May it always be so.", objectives = "Serve tables at the celebration in Bel'ameth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76282] = { id = 76282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Disquieting Feeling", description = "Ah, {name}! You're just the person I was looking for. I'm a little concerned about Khadgar. I don't think it's anything dire, but he doesn't seem to be enjoying himself like everyone else--he just seems... distracted. \n\nI don't want to pry, but perhaps you could bring him a drink for me? He may open up to you.", progress = "Were you able to cheer up Khadgar, {name}?", completion = "Thank you, friend. I knew he'd speak to you.\n\nMaybe now we can both relax.", objectives = "Bring Khadgar a drink in Bel'ameth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76283] = { id = 76283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Andu-falah-dor", description = "My mother asked for us all to meet her by the moonwell.\n\nIt has been long enough. We should not keep her waiting.\n\nSpeak with me there.", completion = "As Amirdrassil blooms into Azeroth beyond the Dream, my sister takes on the mantle of a new Aspect.\n\n<Alexstrasza glances at where the portal was and smiles.>\n\nAnd you, {name}, have drawn all these events to a happy conclusion.", objectives = "Speak with Merithra in Bel'ameth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76284] = { id = 76284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work It", description = "The Trial of Style gives us the opportunity to look good, {class}.\n\nThe camera makes sure we keep looking good. \n\nSo focus on me and my camera, follow my directions and I'll make sure you look fantastic!", progress = "Focus on me and follow my directions. \n\nI'll make sure you look great.", completion = "The camera doesn't lie, {name}. \n\nYou are one stylish {class}.", objectives = "Focus on the photographer and follow their directions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
