quests[76361] = { id = 76361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fashion Week", description = "Ah, the Trial of Style is upon us, {class}. \n\nThe outfits, the creativity, the elegance of the Trial are truly a sight to see.\n\nSpeak to a Trial of Style Envoy to learn more about the event.\n\nA word of warning, those envoys can be... challenging to deal with.", completion = "You really think you're ready for the Trial of Style?\n\nIn that?", objectives = "Speak to a Trial of Style Envoy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76362] = { id = 76362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Antlered Skull", description = "<Despite its surroundings, this skull does not appear to be fel-corrupted.\n\nAs you move your hand closer, you feel a sense of calm emanating from it. \n\nSoridormi will want to see this.>", completion = "<Soridormi gingerly raises the skull to eye level.>\n\nYou said you found this by a fel-corrupted Illidan?\n\nI assume this is Malfurion.\n\nAnd we thought their family problems in our timeline were bad.", objectives = "Bring the Antlered Skull to Soridormi in the Tyrhold Reservoir.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
