quests[76379] = { id = 76379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Murloc and a Dragon Walk into a Time Rift...", description = "Grurguglg.\n\nGuuglrllghulgrgl grugll gur. Murgllgllrugl guglrllg murgu gruggullgl. Murglgurrrr gurgll Gurlgul, guruuuurllgr gurgull gurgllglrl  .\n\nArgurgulul?\n\n<You aren't certain what's being said. This world's version of Alexstrasza is handing you an hourglass and miming flipping it. It is probably of interest to Soridormi.>", completion = "<Soridormi looks at the hourglass you carry.>\n\nThis hourglass is of bronze dragon manufacture. It allows someone to temporarily leap to a different timeway. \n\nYou said that this was given to you by that timeway's iteration of Alexstrasza? \n\n<Soridormi glances at Alexstrasza.>\n\nWell, this should prove interesting.\n\n<Soridormi turns the hourglass over.>", objectives = "Bring the Azmerlothian Hourglass to Soridormi in the Tyrhold Reservoir.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
