quests[76382] = { id = 76382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deadwind Derby - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76384] = { id = 76384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bloom Begins", description = "I sense a change on the wind. Like the dawning rays of the sun. Like petals before they unfurl. A great swelling energy, right at the heart of the Emerald Dream.\n\nThe Bloom. It has begun.", progress = "A bloom so beautiful, yet it brings such dread. Can we truly prevail?", completion = "Amirdrassil is now at its most vulnerable. Whether it shall bloom within Azeroth as a beacon of hope... Or if it shall become a harbinger of doom.\n\nIts fate is ours to protect. And protect it we must.", objectives = "Witness Amirdrassil begin to bloom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76385] = { id = 76385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hazardous Horticulture", description = "We may be outnumbered, but this is my domain. And I have a way of evening our odds.\n\nTake this pouch of seeds. Plant them throughout Wildfire Canyon and the Dream's faerie dragons will transform them into treants.\n\nWith luck, they will draw attention from our front lines and bolster our ground forces.", progress = "Hopefully the faerie dragons are small enough to go unnoticed by Fyrakk's forces.", completion = "I did not expect the Prophet of the Flame to join the fray himself. We may have less time than I thought.", objectives = "Plant 6 Dream Seeds across Wildfire Canyon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76386] = { id = 76386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Clash of Ice and Fire", description = "The Primalists have erected great flame wards throughout their encampment. Yet we know not why. I have asked our ground forces to investigate, but they are blocked at every turn.\n\nTwo fire elementals in particular stand against us, empowered by Fyrakk's shadowflame.\n\nYou must clear the area of enemies. I have imbued this scale with my magic. Use it to weaken the elementals and any other who stands in your way.", progress = "Even in the heat of battle, the Primalists continue to empower those flame wards. But to what end? We must clear the way so that our forces can investigate.", completion = "I am glad my scale was of use to you. Though I cannot take to the field, I can at least empower you to fight on my behalf.\n\nI will tell our ground forces to begin their investigations. We must find out why those flame wards are being empowered.", objectives = "Slay Calderamor, Ignarion, and 15 Wildfire enemies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76387] = { id = 76387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defense of the Ancients", description = "Fyrakk's forces at Skystone Falls are already threatening to overwhelm us. I fear not even the combined might of the Sentinels and Ancients can hold out against them.\n\nThe Ancients are bearing the brunt of the offensive. We have reports of djaradin attempting to capture them for some unknown purpose.\n\nWe cannot allow Igira to succeed in whatever nefarious plan she has in mind. You must seek out the Ancients on the battlefield and free any who are captured.", progress = "The Ancients may be few, but they battle fiercely for our cause. Go, {name}. Help them.", completion = "Your aid has helped the Ancients stand against the djaradin, but for how long? How many more will be lost before this battle is done?\n\nSo much sacrificed for this war. So many fallen. Too many.", objectives = "Free the Ancients at Skystone Falls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76388] = { id = 76388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fighting Fire With Fire", description = "The notes you found, combined with Merithra's reconnaissance, have revealed Ashendir's plan. The flame wards that surround the Wellspring Temple are blocking our reinforcements.\n\nOur allies will distract Fyrakk while you and I slip behind enemy lines to destroy the wards.\n\nThe skies are filled with drakes, and I must fend them off. Once you find a flame ward and thin out its defenses, signal me to destroy it.", completion = "Fyrakk may have retreated, but he still aims to destroy the barrier protecting the Wellspring Temple. We must break through the enemy's ranks and stop him.\n\nIt is there we will put an end to his machinations, once and for all.", objectives = "Clear out Skyfire Turrets and mark Primalist Flame Wards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76389] = { id = 76389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Age of Mortals", description = "Once again, the mortal races have come together to defend a World Tree. It is only fitting then that we bolster their efforts with a relic from that past battle. The Horn of Cenarius.\n\nI entrust the horn to you, {name}. Use it to bestow the blessings of Cenarius to our allies. With luck, it will allow us to break through Fyrakk's forces and open a path to the temple.\n\nAnd do not forget to lend your strength as well. Every enemy felled is one fewer between us and Fyrakk.", completion = "Our allies fight with the blessing of Cenarius! It is only a matter of time until Fyrakk's forces break their ranks and flee before us.", objectives = "Blow the Horn of Cenarius while next to heroes of Azeroth and slay Fyrakk's forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76390] = { id = 76390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inconvenience Fee", description = "I have no idea how you managed to find me or what possessed you to douse a dead guy with holy water, but we can both agree that you owe me. That stuff hurts!\n\nFortunately for you, I like bribes more than my naps. I will happily overlook this horrible first impression you gave so you and I can be best pals; scratch my back and I'll scratch yours.\n\nWhat do you say?", progress = "Hey, that was quick! What did you forget?", completion = "Whoa, look at this haul! You even remembered my coffee. Nobody remembers the coffee...\n\nI like you. We're going to accomplish great things together. By that, I mean you are going to bring me Scourgestones, and I am going to trade you all of the spoils that dungeon delvers of old left behind when they ate dirt. Should have stood back up when they had the chance, like me!\n\nI'll pack my things and meet you in the center ring.", objectives = "Zackett Skullsmash in the rafters of Naxxramas has offered to overlook your transgression in exchange for a variety of items.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76394] = { id = 76394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadows of Flavor", description = "I've set out to create a meal that transcends the ordinary, one that even the emperor wouldn't turn away.\n\nI require ingredients from the darkest of shadows to craft this extraordinary meal. Many consider these ingredients forbidden, but they will become a harmony of light and shadow in my hands.\n\nPlease assist me by harvesting the following ingredients: Shadowblind Grouper, Dark-Nurtured Scallions, and a Vial of Twilight Spice.", progress = "Have you found all of the ingredients?", completion = "Now the magic happens. Please sample this creation for yourself.", objectives = "Collect 10 Shadowblind Grouper, 5 Dark-Nurtured Scallions, and a Vial of Twilight Spice.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76395] = { id = 76395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corruptor's Scourgestones", progress = "I doubt I need to give you the entire spiel about scourgestones, {name}, so I will cut to the chase. I am VERY interested in growing my collection, and you are VERY interested in what I have to offer.\n\nCorruptor's Scourgestones are by far the most powerful, so we can talk business if you only have a few.\n\nAnd don't tell the Argent Dawn about this! It's our little secret, right pal?", completion = "Another batch of scourgestones from my best buddy, {name}! Thanks as always, these will go great with the rest of my hoard. Keep this up, and I will need to find a new place to stash them!\n\nHere's a token for your trouble. I like this little back and forth trading game we got going on here. Let's keep it up.\n\nBut no, I am still not telling you what they're for." }
quests[76396] = { id = 76396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invader's Scourgestones", progress = "I doubt I need to give you the entire spiel about scourgestones, {name}, so I will cut to the chase. I am VERY interested in growing my collection, and you are VERY interested in what I have to offer.\n\nInvader's Scourgestones are rather common, so I ask you bring a decent haul.\n\nAnd don't tell the Argent Dawn about this! It's our little secret, right pal?", completion = "Another batch of scourgestones from my best buddy, {name}! Thanks as always, these will go great with the rest of my hoard. Keep this up, and I will need to find a new place to stash them!\n\nHere's a token for your trouble. I like this little back and forth trading game we got going on here. Let's keep it up.\n\nBut no, I am still not telling you what they're for." }
quests[76397] = { id = 76397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elwynn Forest Flash", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76398] = { id = 76398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aerial Supremacy", description = "The dragonflights have arrived. The skies are ours to reclaim! And you shall help us tip the scales.\n\nMount your drake and target the enemies above. You need only swoop in and take their forces by surprise. Your drake shall handle the rest.", progress = "The faster we can take down Fyrakk's aerial forces, the faster we can make our way to the temple and put a stop to this madness.", completion = "Excellent. Fyrakk's forces are reeling from our assault.\n\nLet us dragons handle the rest, {name}. This is our Dream, and I will not suffer these invaders any longer.", objectives = "Slay 15 enemy proto-drakes flying above the Field of Flames by striking them with your dragonriding mount.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76399] = { id = 76399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elwynn Forest Flash - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76400] = { id = 76400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elwynn Forest Flash - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76401] = { id = 76401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echo of the Firelands", description = "We have finally broken through the enemy's ranks, yet the Prophet of the Flame now bars our path. And he has unleashed his full power.\n\nThe Prophet must be defeated if we have any hope of making our way to the temple. I ask you to face him, champion. We shall hold back his forces as you do so.\n\nThe end is in sight. Let us finally finish this war.", completion = "Fyrakk has broken through the barrier! He must have become desperate once he saw our forces closing in. To use that much shadowflame all at once...", objectives = "Defeat the Prophet of the Flame.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76402] = { id = 76402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amirdrassil, the Dream's Hope: Fyrakk", description = "Fyrakk may have entered the temple, but our fight has not ended. Thanks to your efforts, we have broken through his forces. There is still time to stop him.\n\nYou must gather your allies and follow Fyrakk into the Wellspring Temple. We will cover your flank.\n\nKnow that it is not only Amirdrassil that you protect this day, {name}. All of Azeroth will burn if Fyrakk claims the World Tree. He must be stopped, here and now. This is our final stand.", progress = "Once, Fyrakk sought to free dragonkind. He raged a war against us for that very ideal. What drove him to seek domination instead? Was it the need for revenge? The desire for power?\n\nThe same fire that burns can also renew. Yet Fyrakk's flames would swallow the whole world.", completion = "Amirdrassil is saved, and with it all of Azeroth. Fyrakk's defeat has ensured that.\n\nFrom the champion of the Dragon Isles to the savior of the Emerald Dream. All the dragonflights owe you a great debt, {name}. And we shall not soon forget it.", objectives = "Enter Amirdrassil, the Dream's Hope, and defeat Fyrakk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76403] = { id = 76403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mayhem Incarnate", description = "We need to uncover exactly what Fyrakk's plan is. He is holding his forces away from the tree, but we do not know why.\n\nI can do some scouting, but direct conflict with Fyrakk would not help our cause right now.\n\nFollow me further into the Dream. There is a Primalist encampment to the north. Let us start there, so we can put an end to this madness.", completion = "My claws are here?", objectives = "Speak with Vyranoth near the Primalist encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76404] = { id = 76404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cogs in a Machine", description = "<This cog spiraled out of a mechanized creature as you sent it back to its timeway.\n\nWhile its design is similar to Mechagnome technology, it's sleeker and more refined.\n\nIt bears a small inscription.\n\nSoridormi will want to see this.>", progress = "Hello again, {name}. What do you have there?", completion = "<Soridormi reads the inscription on the cog.>\n\n\"Mechanization is the only way to true peace\".\n\nAn interesting sentiment, but also a lie. This timeway clearly continued to develop weapons for war.\n\nI can't help but wonder: if they weren't fighting each other, what were they fighting?\n\nI'll put this on the tables if you want to look at it later.", objectives = "After completing a Time Rift, return to Soridormi in the Tyrhold Reservoir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76406] = { id = 76406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sins of the Ashbringer", description = "<As you near this blade, you can feel necromantic power thrumming from it.\n\nPerhaps you should wrap the sword in cloth and avoid touching it directly.\n\nSoridormi will want to see this.>", completion = "<As you hold the item to Soridormi, she leans backwards.>\n\nI do not need to get a closer look at that, thank you very much.\n\nWe will put it with the rest of the items. The Ebon Blade can siphon off necromantic energy. That should make it easier to handle.", objectives = "After completing a Time Rift, return to Soridormi in the Tyrhold Reservoir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76407] = { id = 76407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Today, Fate", description = "Eternus intends to show us what happened. I think she also seeks to change the past.\n\nNormally, I would not entertain this idea, but understanding the infinites is the only way forward.", progress = "Eternus has something to show us--I expect we will learn a great deal about her.", completion = "Could it be possible to help Moraidormi? On the surface, it may seem like we can.\n\nBut I sense something is... off here. Why was Vexemia chasing her? What will happen if Vexemia does not move on?\n\nI fell like we are missing something.", objectives = "Enter the Time Rift to witness the past.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76410] = { id = 76410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dark Summons", description = "Denizens of Azeroth,\n\nDo you thirst for power? Do you wish to change your circumstances, to become... more? \n\nMore free.\n\nMore respected.\n\nMore feared.\n\nDo you wish to become a Warlock?\n\nIf your response to any of the above is \"yes\", then meet with my humble servant Phineas.\n\nIn temptation,\n\nMadam Shadow", completion = "Another taker, but wait! {name}? Well now...\n\n... you're just the {class} we've been looking for!", objectives = "Talk to Assistant Phineas in the Mage Quarter in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76416] = { id = 76416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forward Unto Fire", description = "Amirdrassil draws power from the Wellspring Temple in preparation for its bloom. The barrier protecting the temple will not last much longer under Fyrakk's assault.\n\nI have sent messengers all across Azeroth asking for reinforcements, but none have yet arrived. Something blocks their path into the Dream. For now, we must rely on the forces we have.\n\nI ask you to travel to the Verdant Pass. If there is anyone I would have by my side, it is you.", completion = "We are thankful for your arrival, {name}.\n\nOur forces have assembled, but the odds are against us. We will only be able to hold on for so long without reinforcements. Let us hope we can draw Fyrakk's attention until the Bloom is complete.", objectives = "Meet Alexstrasza at the Verdant Pass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76419] = { id = 76419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Violence Will Solve It", description = "Do you not agree that Moraidormi can be saved? We infinites often save those we think suffered needlessly--worthy or not.\n\nSupposedly, Mori died too close to the Caverns of Time just east of us. Using too much time magic here could have... consequences.\n\nBut this should be quick. Chrono-Lord Deios was in possession of artifacts that could forcefully rewind time. The bronze dragonflight has them now. \n\nWe will rewind time and then destroy Vexemia.\n\nSimple.", progress = "This will be easy. Which makes one wonder why the bronze dragonflight did not do it before!", completion = "That... did not go as I had planned.\n\nBut I will not give up! We can just rewind again until we get it right.", objectives = "Rewind time and defend Moraidormi from Vexemia's attack.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76420] = { id = 76420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Butterfly Effects", description = "We were overwhelmed by her companions. Moraidormi was still killed.\n\nI need another strategy, one that will actually protect her. She is what matters. Go rewind time, including our actions.\n\nAfter the rewind, I will hold time in place. Then we can try to make defenses for her.", progress = "What else can we do?", completion = "That was not any better.\n\nIt--it was clearly even worse...\n\nI am trying not to lose focus. What if we attacked again or...", objectives = "After rewinding time, create defenses for Moraidormi and test them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76421] = { id = 76421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate We Make", description = "We just need to be stronger and faster!\n\nWe cannot leave it like this, not with the eggs also destroyed.\n\nI will come up with another idea. Restart time, and...\n\n<Eternus sighs.>\n\nPerhaps I will listen to Nozdormu. He keeps telling me I have \"missed\" something...", progress = "Doing nothing makes no sense to me, but I will be patient. For now.", completion = "Moraidormi. The whelp. I see now.", objectives = "Rewind history again and see what Nozdormu has to say.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76422] = { id = 76422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infinity and Beyond", description = "If we continue to look into the past, we miss out on the present--or even the future.\n\nLet us return to Thaldraszus.\n\nDo not worry about these time fracture elementals. They too will heal with time.\n\nAs we all do.", progress = "I hope this experience can bring us together.", completion = "We all learned something new today.\n\nMyself included.\n\nTime never stops teaching. It falls to all of us to always listen and learn.", objectives = "Return to the present to check in with Chromie.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76423] = { id = 76423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Limits", description = "After confronting the infinites and, well, myself--we have had a lot to think about.\n\nEternus, one of the infinites, has apparently been thinking a lot too.\n\nThe infinites want to change Nozdormu into his infinite form, Murozond. We don't want that. And after learning about Nozdormu, I think Eternus may be persuaded to not want that either.\n\nI've set up a meeting between Nozdormu and Eternus to get them talking. But I want someone else there... in case something goes wrong.", completion = "This will be a... delicate meeting. Allow me to do the talking.", objectives = "Check on Eternus and Nozdormu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76425] = { id = 76425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renowned with the Dream Wardens", description = "Champion! A moment of your time.\n\nWe wanted to recognize all your efforts. Meet me back at Central Encampment. We have a token of our appreciation that we'd like to give you.", completion = "Thank you so much for all that you have done.", objectives = "Speak with Keeper Amrymn at the Central Encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76426] = { id = 76426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kalimdor Cup Circuit", description = "The Riders of Azeroth have learned much from us, and now we test their mettle, as well as yours, skyrider!\n\nMy bronze colleagues have traveled to Kalimdor to create new challenges. They await you with many races across the continent.\n\nAre you up to the task?", progress = "Have you taken wing today?", completion = "You lead the way among your fellow dragonriders! As the Kalimdor Cup continues, find other races there and prove you are a cut above the rest.", objectives = "Fly through the Kalimdor Cup courses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76427] = { id = 76427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dark Summons", description = "Denizens of Azeroth,\n\nDo you thirst for power? Do you wish to change your circumstances, to become... more? \n\nMore free.\n\nMore respected.\n\nMore feared.\n\nDo you wish to become a Warlock?\n\nIf your response to any of the above is \"yes\", then meet with my humble servant Phineas.\n\nIn temptation,\n\nMadam Shadow", completion = "Another taker, but wait! {name}? Well now...\n\n... you're just the {class} we've been looking for!", objectives = "Talk to Assistant Phineas in the Cleft of Shadow in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76429] = { id = 76429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kalimdor Cup Begins", description = "Skyrider! You just missed Lord Andestrasz. He's looking for capable skyriders like yourself to compete in new races!", completion = "Thank you for visiting, dragonrider!", objectives = "Visit Lord Andestrasz in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76430] = { id = 76430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beginning Impositions", description = "Darkest greetings, {race}. Ahem, yes. Yes! Darkest greetings indeed.\n\n<The lanky man seems to suddenly remember where he is.>\n\nOn behalf of my patron, I bid you travel to the Darkmoon Faire. The Faire! Who doesn't love it? Yes. Yes!\n\nAhem.\n\nShe requires your presence, she does! Our Lady of the Midnight Moon. The Damsel of Darkness! The Mother of Crows...\n\n...Madam Shadow.", progress = "Everyone knows the way to the Faire...", completion = "You're... smaller, than I remember.", objectives = "Travel to the Darkmoon Faire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76433] = { id = 76433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashen Soil", description = "It seems the Druids of the Flame wasted no time in seeking to expand their influence. \n\nDeep within these barrow dens, some manner of corruption has taken root. It will spread if left unchecked, consuming the entire den before expanding outwards to threaten the rest of the dream.\n\nTime is short, {name}. Delve into the barrow, seek out the sources of the spreading flame, and excise them before the smoldering embers can grow and spread.", progress = "Make haste. These flames grow brighter by the moment.", completion = "<Tyrande's expression wavers between sadness and conviction.>\n\nThese are not Fandral Staghelm's Druids of the Flame. To think that someone as kind and compassionate as Norana would count herself amongst them...\n\nWe may never truly understand the depth of the scars left by the fallen boughs of Teldrassil.", objectives = "Find and excise the source of the barrow den's flame corruption.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76434] = { id = 76434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Yet Lost", description = "The flame did not take root here on a whim. \n\nNo doubt there are servants of the Firelands cloistered within, trying to spread their flame to the creatures that reside within these barrows. We must do what we can to save those who can still be saved, and mete out swift justice to the heretics that lurk within.", progress = "If even one soul remains languishing within these dens, we must do everything we can to save them.", completion = "Not a day goes by where I do not mark the memories of those that fell at Teldrassil, consumed by a fire that I could not quell. \n\nBe they Kaldorei or Dryad, I will never again let the cries of the anguished go unanswered. Not while I still draw breath.", objectives = "Rescue the denizens of the Sor'theril Barrow Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76435] = { id = 76435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Smoldering Copse", description = "Andi'thur tells me of smoke rising from a grove to the west. Norana's new allies are not exactly the subtle sort.\n\nI do not care what her motivations are. I will not allow her to set another inch of this land ablaze. Ride for the western groves. However the Druids of the Flame plan to seek their so-called rebirth, we will do all we can to stop them.", completion = "Norana... You were always such a kind and quiet soul. To think that you would help spur something so foul.\n\n<Tyrande sighs.>\n\nThere is much to be done.", objectives = "Investigate the Smoldering Copse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76436] = { id = 76436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Scrap of Hope", description = "It is only a matter of time before Fyrakk's forces decimate our own. And then there will be nothing stopping him from entering the Wellspring Temple.\n\nIf the Prophet of the Flame is responsible for blocking our reinforcements from entering the Dream, there must be some record or communication of his plan. We just have to find it.\n\nSearch for any communications amongst Fyrakk's forces at Skystone Falls. If we can disrupt their efforts in some way, we might have a chance to turn the tide.", progress = "If Fyrakk enters the Wellspring Temple, it is not just Amirdrassil that will burn. All of Azeroth will burn with it.", completion = "Let us hope some knowledge can be gained from the communications you collected.\n\n<Alexstrasza pores over the notes you handed her. Her expression slowly changes from grim to hopeful.>\n\nYou might have just saved us all, {name}.", objectives = "Collect 8 Scraps of Parchment from Fyrakk's forces at Skystone Falls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76437] = { id = 76437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Ground", description = "We allowed ourselves to be distracted. We thought the Druids of the Flame had followed us into the Dream, when clearly they arrived before we did.\n\nWith Amirdrassil so close at hand, we cannot allow them to plant their ashen roots here. Release their prisoners. Ransack their supplies. Do whatever you can to ensure that this burning corruption does not spread further.", progress = "We must act quickly. The further this flame-blighted ground spreads, the more danger our allies will face in the days to come.", completion = "Even as warped by flame as they are, these druids have not forgotten the way to the dream. It will be difficult to keep them out entirely.\n\nStill, without a proper base of operations, they will struggle to expand their influence. Your deeds today will help ensure Amirdrassil's safety against this spreading fire.", objectives = "Disrupt the Smoldering Copse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76438] = { id = 76438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurubashi Gala", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76439] = { id = 76439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurubashi Gala - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76440] = { id = 76440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurubashi Gala - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76441] = { id = 76441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grim Reprisal", description = "The Druids of the Flame will not allow you to proceed unfettered once your intentions here become clear.\n\nThey are my kin, my brothers and sisters under Elune... But they seek to undo all that we have toiled for. Their machinations would condemn countless lives to an all-consuming inferno.\n\nI won't allow it. We cannot allow it.\n\nDisrupt their rituals. Destroy their supplies. If they raise their blades against you, cut them down.", progress = "Take heed. These druids' zealotry fuels their reckless ends. Should they identify you as an enemy, they will not show mercy.", completion = "To think, after all we have been through, that any druid would dare try to warp the Dream in such a way.\n\n<Tyrande scowls.>\n\nThese 'druids' are an affront to the suffering that the Kaldorei have endured.", objectives = "Disrupt the Smoldering Copse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76442] = { id = 76442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forlorn Hope", description = "You've arrived just in time. Norana lurks just beyond the ridge. She appears to be taking part in some manner of ritual - alongside a man who appears to be their leader.\n\nThese are powerful druids, and their strength is amplified by their ties to the Firelands. Taking the blade to all of them at once would be foolish.\n\nStill, the least we can do is disrupt their ritual. If we send them scattering, we buy ourselves time - and an opportunity to press the advance elsewhere.", completion = "This so-called Prophet purports to represent the interests of the Kaldorei, but I see him plain enough. He craves power, and he exploits the fear and suffering of the Kaldorei to claim it.\n\nHis work must not continue. Not while I yet draw breath.\n\nWe've done all that we can here, for now. We must return to Amirdrassil.", objectives = "Interrupt the Flame Druids' ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76443] = { id = 76443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Looming Cinder", description = "The Druids of the Flame are nothing more than allies of convenience to Fyrakk and his ilk. Nevertheless, they present a dire threat to the well-being of Amirdrassil, to say nothing of the rest of the Dream.\n\nThe victory we earned here today was hard-fought, but it only served to stem the tide. No doubt the Prophet and the Priestess have already reunited with their erstwhile allies.\n\nWe should return to Merithra. She needs to know of this.", completion = "I am glad to see you return, {class}. Would that I could bid you a moment to rest for all of the hard work that you have done.\n\nUnfortunately, we've no such luxury. Where one flame falters, another flares in response. Amirdrassil remains in danger.", objectives = "Return to Merithra at Amirdrassil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76445] = { id = 76445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ironforge Interceptor", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76446] = { id = 76446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ironforge Interceptor - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76447] = { id = 76447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ironforge Interceptor - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76448] = { id = 76448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Scalecommander Abereth", description = "According to our colleagues, this cave was used to test prospective scalecommanders.\n\nExcuse me. It either tested them or housed their remains. The trials were so difficult that it usually amounted to the same thing.\n\nWe're searching for an ancient scalecommander referenced in our records as \"The Cleaving Blade\": a promising young dracthyr whose future ended abruptly somewhere near this cave. Perhaps we'll discover how their story ends.", progress = "Without those attunement relics we won't be able to solve this mystery, {name}.", completion = "Ah ha! Give them here and I'll calibrate your goggles.", objectives = "Locate the three attunement relics.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76449] = { id = 76449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Endless Conflict", description = "<You notice a book beside the body of a Great Glorious Alliance soldier.\n\nQuickly flicking through the pages, you see that it's some type of journal. \n\nParts of it were ruined by a puddle of oil.\n\nSoridormi will want to see this.>", completion = "<As you hold the book out to Soridormi, she picks it up gingerly between two fingers as oil continues to leak from the book.>\n\nI'm not sure I want to look inside. You said there was legible text still left in this?\n\nWell... I suppose we can put it on the rest of the pile.\n\nAfter it has been cleaned.", objectives = "Bring the Oil-Soaked Log Book to Soridormi in the Tyrhold Reservoir.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76453] = { id = 76453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Stony Reception", description = "<This chipped stone tablet stands out from its surroundings.\n\nAs you go to pick it up, it weighs quite a lot more than you expected.\n\nSoridormi will want to see this.>", completion = "<As you hold the item out to Soridormi, she nearly drops it, as the weight takes her by surprise.>\n\nThis is from the Black Empire? \n\nIt... does not look corrupted. Perhaps we should be careful nonetheless.\n\nI'll have someone come by and cleanse it, just to be sure.", objectives = "Bring the Chipped Stone Tablet to Soridormi in the Tyrhold Reservoir.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76456] = { id = 76456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Using the Idol", description = "Ah, the Idol of Ohn'ahra! Let's use it to find gems. I've hidden three gems nearby in Valdrakken, all outside.\n\nThe idol will reveal the gems when you're near.\n\nCome back when you've tracked them down.", progress = "Have you found the gems?", completion = "You have an eye for seeking lost objects, {name}. This skill will serve you well. \n\nOr should I say... serve US well.", objectives = "Use the Idol of Ohn'ahra to find 3 hidden gems, then speak with Preservationist Kathos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76459] = { id = 76459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Resistance", description = "<The person in front of you is clearly an uncorrupted night elf, albeit significantly more feral and malnourished than usual.>\n\nNice world. No Legion. No fel.\n\nIf you can, send help. Suramar, ask for Tyrande.\n\n<Soridormi may want to see this.>", progress = "Hello again, {name}. What do you have there?", completion = "<Soridormi looks at you in a perplexed manner as you hand her a map to Suramar. Her expression changes as you explain the circumstances.>\n\nIncredible. This world has been under the rule of the Legion for ten thousand years, yet still there is a resistance. \n\nI wish we could help them, but we cannot interfere with another timeway.\n\nA horrible answer, I know.", objectives = "After completing a Time Rift, return to Soridormi in the Tyrhold Reservoir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76460] = { id = 76460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dragon in Hand is Worth Two in the Roost", description = "Ah, {name}, so wonderful to see you!\n\nYou have arrived just in time. I was tasked with seeking out potential allies to aid with the protection of the world tree.\n\nYour accomplishments speak for themselves--your help in this matter would be greatly appreciated.\n\nWhat do you say, up for some diplomacy?", progress = "I'm quite excited to meet these new dragons.", completion = "Well then! We should go meet the representative of the netherwing. \n\nMordenaku is his name. Apparently, he is also a prince.", objectives = "Talk to Wrathion about his potential allies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76461] = { id = 76461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draconic Diplomacy", description = "I suspect Vyranoth might also be interested in recruiting new dragons to our cause... but she'll need a little convincing. \n\nI just so happen to be very good at convincing. \n\nI'll speak with Vyranoth, and we'll meet you in Valdrakken once she's decided to join us.", progress = "The netherwing are a fascinating flight.", completion = "These seem like very reasonable requests. Nothing obscure, nothing secretive. \n\nI'm almost disappointed.\n\nI can handle one, but I may need your help with the rest.", objectives = "Talk to Prince Mordenaku at the Petitioners Concourse in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76462] = { id = 76462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cavern Cleaning", description = "This cave is adequate. It has a commanding view of the surrounding land, and is highly defensible.\n\nBut the state of it is not acceptable. \n\nI will place an enchantment upon you. When you draw near to the smaller spiders, it will freeze them, allowing us to relocate them. The sacs and larger spider will need to be addressed with more... finality. \n\nSee that it is done.", progress = "Have you finished?", completion = "Excellent, {class}. We can clean up the remainder and relocate them to another cave.", objectives = "Clean out the spiders in the cave above the Sand-Lost Sanctum in Thaldraszus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76463] = { id = 76463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delectable Delicacies", description = "Of course we will take care of the netherwhelps.\n\nHowever, we might run low on snacks. The beetles close by are a delicious treat for the little ones. \n\nCan you bring me back some juicy beetle bits? Only the best for the little darlings!", progress = "The whelps just love to gobble up those beetle bits.", completion = "Thank you, {name}. The young ones will love these!\n\nMy goodness. First the obsidian whelps, now this?\n\nI cannot believe I am lucky enough to see this!", objectives = "Retrieve 10 Juicy Beetle Bits from Juicy Beetles in the Ruby Lifepools in Waking Shores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76464] = { id = 76464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thorignir", description = "The Thorignir of Stormheim have the strength and power to greatly aid us in defending Amirdrassil, but they have yet to come to the Dragon Isles. I suspect this... Odyn has interfered with their journey.\n\nWe will go and speak with their matriarch. Wrathion tells me her brood is amenable to your kind, and to assisting others. \n\nWe will investigate.", progress = "We will find out why this brood of storm drakes did not heed the call of the Isles.", completion = "How dare he deny any dragons the right to go anywhere!", objectives = "Speak with the Thorignir Broodmother.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76465] = { id = 76465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon Keeping", description = "First he opposes dragonkind, then he enslaves them, denying them their birthrights.\n\nWe shall visit these so-called \"Halls of Valor,\" defeat any who oppose us, and liberate the storm drakes from that which binds them.\n\nCome along.", progress = "These dragons will be freed.", completion = "The Thorignir are free of that wretched keeper's influence for now--and hopefully for good.", objectives = "Speak to Vyranoth and complete the Storm the Halls of Valor scenario.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76469] = { id = 76469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blasted Lands Bolt", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
