quests[76471] = { id = 76471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blasted Lands Bolt - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76504] = { id = 76504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tricked-Out Thinking Cap", description = "The cap has an amazing function: Put it on, and you'll know where you're going! Let's practice!\n\nThe arrow above me has a clue on it, to another arrow somewhere in Valdrakken. And THAT arrow leads to another...\n\nFollow the arrows until you find them all, and the prize at the end!", progress = "You must wear your cap at all times while contemplating secrets. You never know what frequencies you might tap into, or who might tapping into yours.", completion = "Good work! Now you're a master of thinking!", objectives = "Use the Tricked-Out Thinking Cap to find Fangli's clues, then return to Fangli Hoot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76506] = { id = 76506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dryad Fire Drill" }
quests[76509] = { id = 76509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Sands", description = "description", completion = "The Idol of Ohn'ahra has interesting properties. I believe it can help recover another object I've been seeking.\n\nTake it south of Azim in the Shifting Sands and use it to search for fragments of the Time-Lost Tablet. \n\nIf fortune favors us, you will find all its pieces and make it whole.", objectives = "log", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76510] = { id = 76510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plaguelands Plunge", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
