quests[76521] = { id = 76521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buzzing Boffins", description = "<After running up to you with great speed, this robotic creature does not attack you.\n\nIt is persistent in its desire to be close to you.\n\nIt has the word \"Boffins\" etched into its side.\n\nSoridormi will want to see this.>", progress = "Hello again, {name}. What do you have there?", completion = "<Soridormi sighs.>\n\nIt can stay here... for now.\n\n<Soridormi stares at Boffins.>\n\nI am not in the habit of caring for stray pets.\n\n<Soridormi looks at you, then absent-mindedly pats Boffins on its head.>\n\nI do not have the time, but you can leave it here. Thank you for bringing this to my attention.", objectives = "After completing a Time Rift, return to Soridormi in the Tyrhold Reservoir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76522] = { id = 76522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reverie Of Battle" }
