quests[76530] = { id = 76530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unliving Summons", description = "We need you in Tirisfal, {name}. Come quickly.\n\nThere's a new situation brewing just outside the Ruins of Lordaeron, and it's not looking pretty. I'll get you up to speed when you arrive.", completion = "Thanks for being here. We've got a new problem.", objectives = "Report to Lilian Voss in the Ruins of Lordaeron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76531] = { id = 76531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bar Tab Barrel", objectives = "Donate to taverns across the Dragon Isles to cover the tab!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76532] = { id = 76532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Wellspring", description = "Terro gave his life to protect the Dream. Which means we must see it through.\n\nVyranoth should be able to handle Lethka, we must find Suzska.\n\nI hope Lethka did not attack her first. We should start looking near the Wellspring. \n\nMeet me there so we can continue our search.", progress = "Come on, let's head to the Wellspring.", completion = "Buri is here?", objectives = "Spy on the Wellspring of Life with Buri.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76533] = { id = 76533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dangerous Documentation", description = "<The flickering of a hologram stands out among the surrounding greenery.>\n\nA quick investigation of the item reveals this is some sort of catalog left by a Watcher in its timeway. It details observations of the yaungol, ancestors of the tauren.\n\n<Soridormi will want to see this.>", completion = "<Soridormi swipes her hand through the holographic projection of the yaungol as you hand over the Watcher's Log up.>\n\nFascinating technology! So similar to that of our titans.\n\nI'm sure the log entries in it are interesting to read. I'll put it on the tables if you want to review them.", objectives = "Return to Soridormi in the Tyrhold Reservoir.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76536] = { id = 76536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redridge Rally", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
