quests[76538] = { id = 76538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redridge Rally - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76544] = { id = 76544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasteland Warriors", description = "<This book has what appears to be a modified Horde symbol on it. You recognize it as the Blood Horde symbol you have seen from timeway incursions.\n\nIt is odd it is still here, after the incursion has ended. \n\nThe book has been soaked in blood, though it has long since dried off.\n\nSoridormi might be interested in this.>", progress = "Hello again, {name}. What do you have there?", completion = "<Soridormi flips through the book after you hand it to her.>\n\nOur world has been at war for such a long time against one aggressor or another. \n\nSo has theirs, but they just fight each other, over and over again.\n\nIt would be easy to judge them, but our worlds are both drowned in blood.\n\n<Soridormi looks pensive.>\n\nI will put the book on the table in case you want to read it.", objectives = "After completing a Time Rift, return to Soridormi in the Tyrhold Reservoir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76545] = { id = 76545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brewfest in Valdrakken", description = "Have you heard? Brewfest has made its way here! You should speak to Bragdur Battlebrew in the Artisan's Market--he can tell you all about it.", completion = "Did ye come fer a brew? Hah! We got plenty.", objectives = "Speak to Bragdur Battlebrew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76546] = { id = 76546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mantid Methodology", description = "<This amber sword was left behind as you knocked one of the Mantid back through a time rift.\n\nYou take a moment to ensure it's safe, then place it in your pack.\n\nPerhaps Soridormi would be interested in it.>", progress = "Hello again, {name}. What do you have there?", completion = "<Soridormi turns the blade over in her hands and holds it up to the light.>\n\nThis is the first time I've seen a blade made of pure amber.\n\nIt's a lot sturdier than I expected, and quite dense.\n\nGood find, {name}. I will put it on the table, in case you want to look at it later.", objectives = "After completing a Time Rift, return to Soridormi in the Tyrhold Reservoir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76547] = { id = 76547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All That Glitters...", description = "<Having recently defeated the Time Anomaly in this timeway, you notice this golden vase glittering.\n\nIt is extremely worn, be it by time or something else. You can't make out the details of its carvings along the edges.\n\nBattered as it is, it still manages to give off a warm light, contrasting the chill here. \n\nIt looks very out of place. Soridormi may be interested in it.>", completion = "<Soridormi hefts the vase in her hands.>\n\nYou found this on the top of Icecrown?\n\nThat is... odd.\n\nOur Lich King, at least, was not known for his golden aesthetic, at least not in death.\n\nI will put it on the tables. Thank you, {name}.", objectives = "Return to Soridormi in the Tyrhold Reservoir.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76548] = { id = 76548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fishy Gift", description = "Murglgalgul!\n\nGlulmual, rluu glua ffrl wawawamual. Lalala!\n\nMowua ha mwaaay.\n\n<Murloc You raises a fish up in both of <his/her:their> hands towards you. It seems very officious. Soridormi may want to see this.>", progress = "Hello again, {name}. What do you have there?", completion = "<Soridormi looks at you flatly as you hand her the fish.>\n\nA fish. Why thank you, {name}, I did not think you cared.\n\n\n\nI will put the fish with the other items, after temporally locking it. \n\nRemember this for later: I do not enjoy the smell of rotting fish.", objectives = "After completing a Time Rift, return to Soridormi in the Tyrhold Reservoir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76549] = { id = 76549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreaming in the Dream" }
quests[76550] = { id = 76550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "True Sight" }
quests[76551] = { id = 76551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure Diving" }
quests[76552] = { id = 76552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Sync", description = "While Pedgi had you out killing slimes, I asked the investigators here how we can actually help.\n\nSeems quite a few of them are stuck in time anomalies. Luckily, I've just finished giving the metronographer a few temporal upgrades. It should now help the investigators get back in sync.\n\nBut we need to test it out first. Looks like there's someone nearby who will do the trick.", progress = "Oh, I saw that Pedgi had you collect time slime grime for me. I did not ask for it and I do not need it.\n\n<Melly sighs a long suffering sigh.>\n\nAt least he's trying to be helpful.", completion = "Seems the metronographer worked just as intended! \n\nHow interesting that temporal energies are so similar to music. I wonder if the bronze dragonflight has ever conducted research on the subject...\n\nSorry, rambling. Let's get back to helping Tempo. My next paycheck depends on it.", objectives = "Test the upgraded Metronographer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76554] = { id = 76554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torch - 01", description = "description", sourceObjective = "log", sourceObjectiveStatus = "unverified-source-field" }
quests[76557] = { id = 76557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Without Honor", description = "Ok, the goggles should be calibrated. Looks like the confluence point is right here on the ledge. I wonder what happened to him?", progress = "I wonder what we'll find?", completion = "<Zenata frowns somberly into the distance.> \n\nThe Earth Warder's forces, going after one of their own... what do you think they meant by that?", objectives = "Observe the Scene from the past.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76558] = { id = 76558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Base Control" }
