quests[76562] = { id = 76562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moat Maintenance" }
quests[76564] = { id = 76564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tools of the Dragonkillers", description = "If you're going to go after a dragon, who better to employ than the Djaradin?\n\nLet's see what we can find, {name}.", progress = "Without those attunement relics we won't be able to solve this mystery, {name}.", completion = "Ah ha! Give them here and I'll calibrate your goggles.", objectives = "Locate the three attunement relics.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76566] = { id = 76566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dryad Garden", completion = "Cenarius himself sent you? Wonderful. We need the help.\n\nWe must find that dryad acorn!", objectives = "Speak with Ethidris Creekward in the Root-Bound Sanctuary.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
